(()=>{const go=e=>{const el=e.target?.closest?.('button,a,[role="button"]');if(!el||!/adquirir\s+un\s+plan/i.test(el.textContent||''))return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();try{sessionStorage.setItem('rc_payment_return_pending',JSON.stringify({hash:location.hash,at:Date.now()}))}catch{}location.href='/assets/planes.html?v=20260918-1025#dj-plans'};['pointerdown','mousedown','touchstart','click'].forEach(n=>document.addEventListener(n,go,true));const OLD_FOLDER="https://drive.google.com/drive/folders/1UTIQESYvJcNdKXNsDdDs0dRCrDzs5JvF",NEW_FOLDER="https://drive.google.com/drive/folders/1iwuKlMfb8JSLV86ZlbPNQg1ri2Q0CeNl",API="https://rcmusic-eventos-dev-proxy.onrender.com/api",SUPABASE="https://fzqpmpgbubpmongodcat.supabase.co";const patchLabel=()=>document.querySelectorAll("button").forEach(button=>{const w=document.createTreeWalker(button,NodeFilter.SHOW_TEXT),nodes=[];let n;while(n=w.nextNode())nodes.push(n);nodes.forEach(t=>{if(t.nodeValue.includes("Backup actualizado en Drive"))t.nodeValue=t.nodeValue.replace("Backup actualizado en Drive","Actualización y Utilidades Dj.")})});const originalOpen=window.open;window.open=(url,...args)=>originalOpen.call(window,url===OLD_FOLDER?NEW_FOLDER:url,...args);const headers=()=>{const s=localStorage.getItem("rc_drive_session")||sessionStorage.getItem("rc_drive_session")||"";return {"Content-Type":"application/json",...(s?{"X-Drive-Session":s}:{})}};const grant=async email=>{if(!email)return;try{await fetch(`${API}/drive/grant-folder-access`,{method:"POST",headers:headers(),credentials:"include",body:JSON.stringify({email})})}catch{}};const getEmail=b=>{let x=b;for(let i=0;i<6&&x;i++,x=x.parentElement){const m=x.innerText?.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);if(m)return m[0].toLowerCase()}return ""};document.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(/^(Aprobar|Aceptar|Approve|Accept)/i.test(b.textContent.trim())){const email=getEmail(b);if(email)setTimeout(()=>grant(email),1800)}},true);const nativeFetch=window.fetch.bind(window);window.fetch=async(input,init={})=>{const url=typeof input==='string'?input:(input?.url||'');const isTrial=url.includes('/rest/v1/rpc/dj_start_trial');const response=await nativeFetch(input,init);if(isTrial&&response.ok){try{const payload=typeof init.body==='string'?JSON.parse(init.body):{};const auth=new Headers(init.headers||{}).get('Authorization')||'';response.clone().json().then(async data=>{const row=Array.isArray(data)?data[0]:data;if(!row?.generated_code||!auth||!payload.p_email)return;const key=`rc_demo_code_mailed:${payload.p_email.toLowerCase()}:${row.generated_code}`;if(sessionStorage.getItem(key))return;const mailed=await nativeFetch(`${SUPABASE}/functions/v1/send-subscription-email`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':auth},body:JSON.stringify({to:payload.p_email,displayName:payload.p_display_name||'DJ',code:row.generated_code,planLabel:'Demo gratuita',expiresAt:row.plan_expires_at||''})});if(mailed.ok)sessionStorage.setItem(key,'1')}).catch(()=>{})}catch{}}return response};patchLabel();new MutationObserver(patchLabel).observe(document.documentElement,{childList:true,subtree:true})})();
